// Overusing any — silently unsafe:
function total(items: any): number {
  return items.reduce((sum: any, i: any) => sum + i.price, 0);
}

// Prefer a real type instead:
function totalSafe(items: { price: number }[]): number {
  return items.reduce((sum, i) => sum + i.price, 0);
}

let value: unknown = 4;
value = "hello"; // fine — unknown accepts any value, just like any
value = true;    // still fine

let value: unknown = "hello";

console.log(value.toUpperCase());
// Error: Object is of type 'unknown'.

let value: unknown = "hello";

if (typeof value === "string") {
  console.log(value.toUpperCase()); // fine — TypeScript knows it's a string here
} else {
  console.log("not a string");
}

